void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    fragColor = textureLod(iChannel0, fragCoord / iResolution.xy, 0.0);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{  
    float speed = 0.3;
    float c_re = 0.8*cos(iTime*speed);
    float c_im = 0.6*sin(iTime*speed);
    vec2 R = iResolution.xy;

    if(iMouse.z > 0.5) {
        c_re = 2.*iMouse.x / R.x - 1.;
        c_im = 2.*iMouse.y / R.y - 1.;
    }

    mat4 rend1 = inverse(mat4(c_re, c_im, 0.0, 0.0, -c_im, c_re, 0.0, 0.0, c_re, c_im, 0.5, 0.0, -c_im, c_re, 0.0, -0.866));
    mat4 rend2 = inverse(mat4(c_re, c_im, 0.0, 0.0, -c_im, c_re, 0.0, 0.0, c_re, c_im, -1.0, 0.0, -c_im, c_re, 0.0, 1000.0));
    mat4 rend3 = inverse(mat4(c_re, c_im, 0.0, 0.0, -c_im, c_re, 0.0, 0.0, c_re, c_im, 0.5, 0.0, -c_im, c_re, 0.0, 0.866));


    float matscale=1.;
    mat4 transforms[] = mat4[](
        matscale*rend1,
        matscale*rend2,
        matscale*rend3
    );

    //Borders in complex coords.
    float c_abs = c_re*c_re+c_im*c_im;
    float border_mult = 1. / abs(c_abs-1.);
    vec2 LB = vec2(-5, -3.0)*border_mult;
    vec2 RT = vec2(1., 3.0)*border_mult;

    vec2 samples[] = vec2[](
        vec2(0, 0),
        vec2(0.2, 0),
        vec2(0, 0.2),
        vec2(-0.2, 0),
        vec2(0, -0.2)
    );

    if (iFrame == 0 || (iMouse.w > 0.5)) {
        fragColor = vec4(0.05);
    } else {
        float accumulate = 0.0;

        for (int s = 0; s < samples.length(); s++) {
            for (int t = 0; t < transforms.length(); t++) {

                vec2 p = LB + (RT - LB) * (fragCoord + samples[s]) / R.y;
                vec4 pA = transforms[t] * vec4(p, 1.0, 1.0);

                vec2 xyt = (pA.xy - LB)*R.y/R / (RT - LB);

                //ec2 p = LB + (RT - LB) * (fragCoord + samples[s]) / iResolution.xy;
                //vec4 pA = transforms[t] * vec4(p, 1.0, 1.0);
                //vec2 xyt = (pA.xy - LB) / (RT - LB);

                float texFetch = textureLod(iChannel0, xyt, 0.0).x;
                if (xyt.x >= 0.0 && xyt.y >= 0.0 && xyt.x < 1.0 && xyt.y < 1.0) {
                    accumulate += texFetch;
                }
            }
        }

        //float rescale = pow(max(accumulate, 0.0) / float(samples.length()), 0.7);
        float rescale = pow(max(accumulate, 0.0) / float(samples.length()), 0.5);

        fragColor = vec4(rescale * 0.4, rescale, rescale, 1.0);
    }
}
